                    </Button>
                  }
                />
              </div>
            ) : (
              <div className="mt-3 space-y-2.5">
                {habits.map((habit, index) => (
                  <HabitRow
                    key={habit.id}
                    habit={habit}
                    date={date}
                    isDark={isDark}
                    index={index}
                  />
                ))}
              </div>
            )}
          </section>
        </>
      )}

      {formOpen ? <HabitForm open onClose={() => setFormOpen(false)} /> : null}
    </div>
